import { action, v } from "@wizard/sdk";

export default action({
  args: {},
  handler: async (ctx) => {
    const t = await ctx.runQuery("ticketAvailability", {});
    const holder = { holder_phone: "x" };
    await ctx.connectors.telegram.sendToUser({ userId: "u", text: `Телефон: ${holder.holder_phone}` });
    return t;
  },
});
